def transform(grid):
    # Each 3x3 patch encodes one output cell; ignore the background (5).
    out = []
    for tr in range(4):
        row = []
        for tc in range(4):
            counts = {}
            for r in range(3 * tr, 3 * tr + 3):
                for c in range(3 * tc, 3 * tc + 3):
                    v = grid[r][c]
                    if v != 5:
                        counts[v] = counts.get(v, 0) + 1
            row.append(max(counts, key=counts.get) if counts else 5)
        out.append(row)
    return out
